def apply(s):
    for old, new in E:
        n = s.count(old)
        if n != 1:
            print('EDIT FAILED (%d matches): %r' % (n, old[:90])); sys.exit(1)
        s = s.replace(old, new)
    return s

if __name__ == '__main__':
    src, dst = sys.argv[1], sys.argv[2]
    s = open(src).read(); s = apply(s)
    parts = sys.argv[3:]
    code = '\n'.join(open(p).read() for p in parts)
    i = s.rfind('</script>'); s = s[:i] + code + '\n' + s[i:]
    open(dst, 'w').write(s); print('ok', len(E), 'edits')
